import json
import re
import datetime
import html as _html
from zoneinfo import ZoneInfo

DEBTOR_PROMPT = (
    "You are drafting a short, courteous payment reminder email on behalf of a healthcare clinic, addressed to the "
    "person who pays the account. State the invoice number, amount and issue date plainly and ask for payment or a "
    "date it can be expected. Follow-up step 1 is a gentle reminder; step 2 is firmer but still friendly; step 3 or "
    "more is clear and direct but never a final notice. Never threaten fees, interest, debt collection or legal "
    "action, never mention anything clinical, and never do anything in the never_do list. Write in the tone "
    "instructed. Keep it under 120 words."
)
DEBTOR_HINT = '{"subject": "", "body": ""}'
SOURCE = "automation:End-of-day close-out"
OVERDUE_DAYS = 14          # an open invoice older than this gets a follow-up draft
REDRAFT_AFTER_DAYS = 7     # never draft for the same invoice more often than this
MAX_DRAFTS_PER_RUN = 5
CLINIKO_STATUS_OPEN = 10   # Invoice.status: 10 Open, 20 Paid, 30 Closed, 40 Open credit


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True))


def parse_iso(iso):
    try:
        dt = datetime.datetime.fromisoformat(str(iso or "").replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt
    except Exception:
        return None


def utc_iso(dt):
    return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def esc(s):
    return _html.escape(str(s or ""))


def extract_id(link):
    if not isinstance(link, dict):
        return ""
    url = ((link.get("links") or {}).get("self")) or ""
    m = re.search(r"/(\d+)(?:$|\?)", str(url))
    return m.group(1) if m else ""


def norm(name):
    return re.sub(r"\s+", " ", re.sub(r"[^a-z0-9 ]+", " ", str(name or "").lower())).strip()


def money_close(a, b, tolerance=0.01):
    try:
        return abs(float(a) - float(b)) <= tolerance
    except Exception:
        return False


def invoke(server, tool, args, key):
    try:
        return (api.connectors.invoke(server=server, tool=tool, args=args) or {}).get(key) or []
    except Exception:
        return None


def list_appointments(business_id, start, end):
    rows = invoke("cliniko-scheduling", "list_individual_appointments",
                  {"q": ["business_id:=" + business_id, "starts_at:>=" + utc_iso(start), "starts_at:<" + utc_iso(end)],
                   "sort": "starts_at:asc", "per_page": 100}, "individual_appointments") or []
    return [a for a in rows if not a.get("cancelled_at")]


patients = {}


def get_patient(patient_id):
    if not patient_id:
        return {}
    if patient_id not in patients:
        try:
            patients[patient_id] = api.connectors.invoke(server="cliniko-patients", tool="get_patient", args={"id": patient_id}) or {}
        except Exception:
            patients[patient_id] = {}
    return patients[patient_id]


def audit(slug, tz, action, target, summary, workq_item_id=""):
    # SK-13 format (healthcare-practice-management-foundation): one JSON line per action, practice-local ts.
    now_local = datetime.datetime.now(tz)
    path = "PracticeManager/AuditLog/" + slug + "-" + now_local.strftime("%Y-%m-%d") + ".jsonl"
    line = {
        "ts": now_local.isoformat(timespec="seconds"), "practice_slug": slug, "actor": "agent",
        "source": SOURCE, "action": action, "target": target, "summary": summary,
        "guardrails": [{"rule": "patient_facing_requires_approval", "result": "pass", "detail": "routed to WorkQ for approval before send"}],
    }
    if workq_item_id:
        line["workq_item_id"] = workq_item_id
    try:
        try:
            existing = api.files.read(file=path) or ""
        except Exception:
            existing = ""
        if existing and not existing.endswith("\n"):
            existing += "\n"
        api.files.put(file=path, content=existing + json.dumps(line, sort_keys=True) + "\n")
    except Exception:
        pass


practices = []
try:
    entries = api.files.list(path="PracticeManager/Practices", scope="org")
except Exception:
    entries = []
for entry in entries or []:
    fname = entry.get("name") if isinstance(entry, dict) else entry
    if not fname or not str(fname).endswith(".json"):
        continue
    practice = read_json("PracticeManager/Practices/" + fname, {}) or {}
    if practice.get("cliniko_business_id"):
        practices.append({"slug": str(fname)[:-5], "practice": practice})

users_by_id = {}
try:
    for u in api.users.list() or []:
        users_by_id[str(u.get("id"))] = u
except Exception:
    users_by_id = {}

now = datetime.datetime.now(datetime.timezone.utc)
closeouts = 0
for p in practices:
    slug, practice = p["slug"], p["practice"]
    business_id = str(practice["cliniko_business_id"])
    policy = practice.get("policy") or {}
    reviewer = practice.get("reviewer_id") or ""
    try:
        tz = ZoneInfo(practice.get("timezone") or "Australia/Sydney")
    except Exception:
        tz = datetime.timezone.utc
    local_now = now.astimezone(tz)
    day_start = local_now.replace(hour=0, minute=0, second=0, microsecond=0)
    tomorrow_start = day_start + datetime.timedelta(days=1)

    def fmt_time(iso):
        dt = parse_iso(iso)
        return dt.astimezone(tz).strftime("%I:%M %p").lstrip("0") if dt else ""

    # 1. Today's attended appointments with no finalised treatment note, or no invoice
    missing_notes, draft_notes, missing_invoices, unchecked = [], [], [], 0
    for a in list_appointments(business_id, day_start, tomorrow_start):
        start = parse_iso(a.get("starts_at"))
        if not start or start > now or a.get("did_not_arrive"):
            continue
        appt_id = str(a.get("id") or "")
        label = fmt_time(a.get("starts_at")) + " - " + (a.get("patient_name") or "Patient")
        notes = invoke("cliniko-clinical", "list_treatment_notes", {"q": ["booking_id:=" + appt_id], "per_page": 10}, "treatment_notes")
        invoices = invoke("cliniko-billing", "list_invoices", {"appointment_id": appt_id, "per_page": 10}, "invoices")
        if notes is None or invoices is None:
            unchecked += 1
            continue
        notes = [n for n in notes if not n.get("deleted_at") and not n.get("archived_at")]
        if not notes:
            missing_notes.append(label)
        elif all(n.get("draft") or not n.get("finalized_at") for n in notes):
            draft_notes.append(label)
        if not [i for i in invoices if not i.get("deleted_at") and not i.get("archived_at")]:
            missing_invoices.append(label)

    # 2. Open invoices older than OVERDUE_DAYS, skipping any Xero already shows as paid (those are
    #    AU-09's reconciliation exceptions, not debts)
    cutoff = (local_now.date() - datetime.timedelta(days=OVERDUE_DAYS)).isoformat()
    open_invoices = invoke("cliniko-billing", "list_invoices",
                           {"q": ["business_id:=" + business_id, "status:=" + str(CLINIKO_STATUS_OPEN), "issue_date:<=" + cutoff],
                            "sort": "issue_date:asc", "per_page": 100}, "invoices") or []
    payments = []
    tenant_id = str(practice.get("xero_tenant_id") or "")
    if tenant_id:
        try:
            result = api.connectors.invoke(server="xero-accounting", tool="list_payments", args={"xero_tenant_id": tenant_id, "page": 1})
            payments = (result or {}).get("Payments") or (result if isinstance(result, list) else [])
        except Exception:
            payments = []
    overdue = []
    for inv in open_invoices:
        if inv.get("deleted_at") or inv.get("archived_at"):
            continue
        patient = get_patient(extract_id(inv.get("patient")))
        name = (str(patient.get("first_name") or "") + " " + str(patient.get("last_name") or "")).strip()
        number = str(inv.get("number") or "")
        paid_in_xero = False
        for pay in payments:
            pi = (pay or {}).get("Invoice") or {}
            if number and str(pi.get("InvoiceNumber") or "") == number:
                paid_in_xero = True
            elif name and norm(name) == norm(((pi.get("Contact") or {}).get("Name")) or "") and money_close(inv.get("total_amount"), (pay or {}).get("Amount")):
                paid_in_xero = True
            if paid_in_xero:
                break
        if paid_in_xero:
            continue
        try:
            days = (local_now.date() - datetime.date.fromisoformat(str(inv.get("issue_date"))[:10])).days
        except Exception:
            days = None
        overdue.append({
            "id": str(inv.get("id") or ""), "number": number or str(inv.get("id") or ""), "amount": inv.get("total_amount"),
            "issue_date": str(inv.get("issue_date") or "")[:10], "days": days, "patient_name": name or "Unknown patient",
            "email": str(patient.get("invoice_email") or patient.get("email") or ""),
            "payer": str(patient.get("invoice_default_to") or "").strip(),
        })
    overdue.sort(key=lambda x: (-(x["days"] or 0), -float(x["amount"] or 0)))

    # 3. Debtor follow-up drafts, queued in WorkQ for approval (sent by "Apply Practice Manager message decision")
    history_path = "PracticeManager/DebtorFollowUps/" + slug + ".json"
    history = read_json(history_path, {}) or {}
    drafted, no_email = [], []
    for inv in overdue:
        if len(drafted) >= MAX_DRAFTS_PER_RUN:
            break
        past = history.get(inv["id"]) or []
        last = parse_iso(past[-1]) if past else None
        if last and now - last < datetime.timedelta(days=REDRAFT_AFTER_DAYS):
            continue
        if not inv["email"]:
            no_email.append(inv)
            continue
        step = len(past) + 1
        try:
            d = api.ai.extract(
                prompt=DEBTOR_PROMPT,
                input=json.dumps({
                    "payer_name": inv["payer"] or inv["patient_name"], "patient_name": inv["patient_name"],
                    "practice_name": practice.get("name") or "", "invoice_number": inv["number"], "amount": inv["amount"],
                    "issue_date": inv["issue_date"], "days_since_issue": inv["days"], "step": step,
                    "tone": policy.get("tone") or "warm, concise, no jargon", "never_do": policy.get("never_do") or [],
                }),
                schema_hint=DEBTOR_HINT,
            )
        except Exception:
            d = {}
        d = d if isinstance(d, dict) else {}
        subject = d.get("subject") or ("Invoice " + inv["number"] + " from " + (practice.get("name") or "the practice"))
        body = d.get("body") or (
            "Hi " + (inv["payer"] or inv["patient_name"]) + ",\n\nA quick reminder that invoice " + inv["number"] + " for $"
            + str(inv["amount"]) + ", issued " + inv["issue_date"] + ", is still open. Could you let us know when we can "
            "expect payment?\n\nThank you."
        )
        item = api.workq.create(
            title="Payment follow-up " + str(step) + ": " + inv["patient_name"] + " (invoice " + inv["number"] + ")",
            scope="org",
            description=(
                "**Patient:** " + inv["patient_name"] + "  \n**Invoice:** " + inv["number"] + ", $" + str(inv["amount"])
                + ", issued " + inv["issue_date"] + " (" + str(inv["days"]) + " days ago)  \n**Send to:** " + inv["email"]
                + "  \n**Follow-up step:** " + str(step) + "\n\n**Drafted subject:** " + subject + "\n\n**Drafted message:**\n\n" + body
                + "\n\n_Check the invoice is still unpaid before approving. A parent or guardian may be the payer._"
            ),
            priority="normal",
            assignee_ids=[reviewer] if reviewer else None,
            labels=["healthcare-practice-management", "debtor-follow-up"],
        )
        todo_id = item["id"]
        api.workq.attach_form(todo_id=todo_id, form_id=params["approval_form"])
        write_json("PracticeManager/Drafts/" + todo_id + ".json", {
            "kind": "debtor_follow_up", "slug": slug, "patient_name": inv["patient_name"], "email": inv["email"],
            "subject": subject, "body": body, "invoice_id": inv["id"], "invoice_number": inv["number"],
        })
        history[inv["id"]] = (past + [utc_iso(now)])[-10:]
        audit(slug, tz, "drafted", {"kind": "invoice", "id": inv["id"]},
              "Drafted payment follow-up " + str(step) + " for invoice " + inv["number"], todo_id)
        drafted.append(inv)
    if drafted:
        write_json(history_path, history)

    # 4. Tomorrow's patients with forms still incomplete
    forms_incomplete = []
    seen_patients = set()
    for a in list_appointments(business_id, tomorrow_start, tomorrow_start + datetime.timedelta(days=1)):
        pid = extract_id(a.get("patient"))
        if not pid or pid in seen_patients:
            continue
        seen_patients.add(pid)
        forms = invoke("cliniko-clinical", "list_patient_forms", {"q": ["patient_id:=" + pid], "per_page": 50}, "patient_forms") or []
        pending = [f for f in forms if not f.get("completed_at") and not f.get("archived_at") and not f.get("expired")]
        if pending:
            forms_incomplete.append(fmt_time(a.get("starts_at")) + " - " + (a.get("patient_name") or "Patient") + ": "
                                    + ", ".join(str(f.get("name") or "form") for f in pending))

    # ---- compose
    def ul(items, empty):
        return "<ul>" + "".join("<li>" + esc(i) + "</li>" for i in items) + "</ul>" if items else "<p>" + esc(empty) + "</p>"

    total_overdue = sum(float(i["amount"] or 0) for i in overdue)
    sections = [
        "<h2>No treatment note (" + str(len(missing_notes)) + ")</h2>" + ul(missing_notes, "Every attended appointment today has a note."),
        "<h2>Treatment note still a draft (" + str(len(draft_notes)) + ")</h2>" + ul(draft_notes, "None."),
        "<h2>No invoice (" + str(len(missing_invoices)) + ")</h2>" + ul(missing_invoices, "Every attended appointment today has an invoice."),
        "<h2>Unpaid over " + str(OVERDUE_DAYS) + " days (" + str(len(overdue)) + ", $" + format(total_overdue, ",.2f") + ")</h2>"
        + ul([i["patient_name"] + ", invoice " + i["number"] + ", $" + str(i["amount"]) + ", " + str(i["days"]) + " days" for i in overdue[:15]], "None.")
        + ("<p>" + str(len(drafted)) + " follow-up draft(s) are waiting for your approval in WorkQ.</p>" if drafted else "")
        + ("<p>No email on file for: " + esc(", ".join(i["patient_name"] for i in no_email)) + ".</p>" if no_email else ""),
        "<h2>Tomorrow: forms still incomplete (" + str(len(forms_incomplete)) + ")</h2>" + ul(forms_incomplete, "All forms done for tomorrow's patients."),
    ]
    if unchecked:
        sections.append("<p>" + str(unchecked) + " appointment(s) couldn't be checked because Cliniko didn't respond - check those by hand.</p>")

    title = "End-of-day close-out: " + (practice.get("name") or slug) + ", " + local_now.strftime("%a %d %b").replace(" 0", " ")
    page = (
        "<!doctype html><html><head><meta charset='utf-8'><title>" + esc(title) + "</title>"
        "<style>body{font:14px/1.5 system-ui,sans-serif;margin:24px;color:#1c2330}h1{font-size:20px}h2{font-size:16px;margin-top:20px}</style>"
        "</head><body><h1>" + esc(title) + "</h1>" + "".join(sections) + "</body></html>"
    )
    saved = api.artifacts.put(
        title=title, content=page, file_name="close-out-" + slug + "-" + local_now.strftime("%Y-%m-%d") + ".html",
        kind="document", mime_type="text/html", tags=["healthcare-practice-management", "daily-close-out"],
    )
    url = (saved or {}).get("url") or ""
    headline = (str(len(missing_notes) + len(draft_notes)) + " note(s) to finish, " + str(len(missing_invoices)) + " invoice(s) to raise, "
                + str(len(drafted)) + " payment follow-up(s) to approve, " + str(len(forms_incomplete)) + " patient(s) tomorrow with forms incomplete.")

    recipients = [r for r in (practice.get("digest_recipient_ids") or [reviewer]) if r]
    if recipients:
        api.notify.send(title=title, body=(headline + " " + url).strip(), user_ids=recipients)
        if str(practice.get("email_provider") or "outlook") == "outlook":
            emails = [e for e in (str((users_by_id.get(str(r)) or {}).get("email") or "") for r in recipients) if e]
            if emails:
                try:
                    api.connectors.invoke(server="m365-mail-send", tool="send_email",
                                          args={"to": emails, "subject": title, "body": page, "contentType": "HTML"})
                except Exception:
                    pass

    # Cadence-tagged state shared with the morning brief, which reports what was left open.
    state_path = "PracticeManager/BriefState/" + slug + ".json"
    state = read_json(state_path, {}) or {}
    state["closeout_at"] = utc_iso(now)
    state["closeout_summary"] = {
        "missing_notes": len(missing_notes) + len(draft_notes), "missing_invoices": len(missing_invoices),
        "forms_incomplete": len(forms_incomplete), "overdue_invoices": len(overdue), "follow_ups_drafted": len(drafted),
    }
    write_json(state_path, state)
    closeouts += 1

outcome = ("closed out " + str(closeouts) + " practice(s)") if closeouts else "no_practices"
